    ctx.beginPath();
    ctx.arc(x,y,d.r,0,Math.PI*2);
    ctx.fillStyle = `rgba(90,120,220,${alpha})`;
    ctx.fill();
  });

  // destination pulse markers
  destinations.forEach(d=>{
    const [x,y] = toPx(d.nx, d.ny);
    const pulse = (time*0.6 + d.nx*3) % 1;
    // expanding ring
    ctx.beginPath();
    ctx.arc(x,y, 4 + pulse*14, 0, Math.PI*2);
    ctx.strokeStyle = `rgba(140,170,255,${(1-pulse)*0.5})`;
    ctx.lineWidth = 1.5;
    ctx.stroke();
    // core dot
    ctx.beginPath();
    ctx.arc(x,y,3,0,Math.PI*2);
    ctx.fillStyle = 'rgba(200,215,255,0.95)';
    ctx.shadowColor = 'rgba(150,180,255,0.9)';
    ctx.shadowBlur = 6;
    ctx.fill();
    ctx.shadowBlur = 0;
  });

  // hub marker (Singapore) - bright pulsing core with rings
  const hubPulse = 0.5 + 0.5*Math.sin(time*2.2);
  for(let ring=0; ring<3; ring++){
    const rp = ((time*0.5) + ring/3) % 1;
    ctx.beginPath();
    ctx.arc(hubPx[0], hubPx[1], 6 + rp*46, 0, Math.PI*2);
    ctx.strokeStyle = `rgba(160,120,255,${(1-rp)*0.45})`;
    ctx.lineWidth = 1.6;
    ctx.stroke();
  }
  ctx.beginPath();
  ctx.arc(hubPx[0], hubPx[1], 5 + hubPulse*1.5, 0, Math.PI*2);
  const hubGrad = ctx.createRadialGradient(hubPx[0],hubPx[1],0,hubPx[0],hubPx[1],10);
  hubGrad.addColorStop(0,'#ffffff');
  hubGrad.addColorStop(0.4,'#a78bfa');
  hubGrad.addColorStop(1,'rgba(139,92,246,0)');
  ctx.fillStyle = hubGrad;
  ctx.shadowColor = '#a78bfa';
  ctx.shadowBlur = 20;
  ctx.fill();
  ctx.shadowBlur = 0;

  requestAnimationFrame(frame);
}

