window.addEventListener('resize', resize);
resize();

// ---- Geographically-derived landmass paths ----
// Points are projected from real lon/lat via an equirectangular projection
// (lon 20°E..155°E -> x 0..1, lat 50°N..-45°S -> y 0..1) so every blob and
// every destination marker below share one consistent, accurate coordinate space.
function geo(lon, lat){
  const LON_MIN=20, LON_MAX=155, LAT_MAX=50, LAT_MIN=-45;
  return [ (lon-LON_MIN)/(LON_MAX-LON_MIN), (LAT_MAX-lat)/(LAT_MAX-LAT_MIN) ];
}

const landmasses = [
  // Asia mainland (China / Mongolia / Siberia / Central Asia)
  [geo(60,48),geo(90,50),geo(145,50),geo(127,38),geo(122,30),geo(108,22),geo(98,25),geo(80,30),geo(68,38)],
  // South Asia (Indian subcontinent)
  [geo(68,32),geo(85,30),geo(92,25),geo(94,16),geo(80,8),geo(72,15),geo(68,24)],
  // SE Asia peninsula + Indonesian archipelago
  [geo(98,20),geo(106,22),geo(105,10),geo(103,2),geo(98,-2),geo(110,-7),geo(114,2),geo(122,12),geo(100,15)],
  // Japan
  [geo(130,32),geo(132,35),geo(140,36),geo(142,45),geo(140,38),geo(135,33)],
  // Australia
  [geo(113,-22),geo(131,-12),geo(142,-11),geo(153,-27),geo(151,-34),geo(145,-38),geo(115,-34),geo(115,-32)],
  // East Africa / Horn of Africa (partial, edge of frame)
  [geo(33,31),geo(43,12),geo(51,11),geo(40,-2),geo(35,-15),geo(32,-26),geo(20,-30),geo(20,20),geo(25,32)],
];

// Convert normalized polygon points to a dense set of dot coordinates via rasterization
function pointInPoly(x,y,poly){
  let inside=false;
  for(let i=0,j=poly.length-1;i<poly.length;j=i++){
    const xi=poly[i][0], yi=poly[i][1], xj=poly[j][0], yj=poly[j][1];
    const intersect = ((yi>y)!==(yj>y)) && (x < (xj-xi)*(y-yi)/(yj-yi+0.0000001)+xi);
    if(intersect) inside=!inside;
  }
  return inside;
}

let dots = [];
function buildDots(){
  dots = [];
  const cols = 72, rows = 48;
  for(let i=0;i<=cols;i++){
    for(let j=0;j<=rows;j++){
      const x = i/cols, y = j/rows;
      for(const poly of landmasses){
        if(pointInPoly(x,y,poly)){
          dots.push({
            nx:x, ny:y,
            phase: Math.random()*Math.PI*2,
            speed: 0.6 + Math.random()*0.8,
            r: 1.1 + Math.random()*0.9
          });
          break;
        }
      }
    }
  }
}
buildDots();

