function toPx(nx, ny){
  return [nx*W, ny*H];
}

function quadArc(p0, p1, t){
  // control point bows upward/outward for a 3D globe-ish arc
  const mx = (p0[0]+p1[0])/2;
  const my = (p0[1]+p1[1])/2 - Math.abs(p1[0]-p0[0])*0.28 - 40;
  const x = (1-t)*(1-t)*p0[0] + 2*(1-t)*t*mx + t*t*p1[0];
  const y = (1-t)*(1-t)*p0[1] + 2*(1-t)*t*my + t*t*p1[1];
  return [x,y];
}

function drawArc(p0, p1, alpha){
  ctx.beginPath();
  const steps = 40;
  for(let i=0;i<=steps;i++){
    const [x,y] = quadArc(p0,p1,i/steps);
    if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
  }
  ctx.strokeStyle = `rgba(120,150,255,${alpha})`;
  ctx.lineWidth = 1.2;
  ctx.stroke();
}

let t0 = null;
function frame(ts){
  if(t0===null) t0 = ts;
  const time = (ts - t0)/1000;

  ctx.clearRect(0,0,W,H);

  // subtle grid background
  ctx.save();
  ctx.globalAlpha = 0.25;
  ctx.strokeStyle = '#16203a';
  ctx.lineWidth = 1;
  const gap = 34;
  for(let x=0;x<W;x+=gap){ ctx.beginPath(); ctx.moveTo(x,0); ctx.lineTo(x,H); ctx.stroke(); }
  for(let y=0;y<H;y+=gap){ ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(W,y); ctx.stroke(); }
  ctx.restore();

  // radial glow behind hub
  const hubPx = toPx(hub.nx, hub.ny);
  const glow = ctx.createRadialGradient(hubPx[0],hubPx[1],0,hubPx[0],hubPx[1],220);
  glow.addColorStop(0, 'rgba(120,140,255,0.22)');
  glow.addColorStop(1, 'rgba(120,140,255,0)');
