function frame(ts){
  if(t0===null) t0 = ts;
  const time = (ts - t0)/1000;

  ctx.clearRect(0,0,W,H);

  // subtle grid background
  ctx.save();
  ctx.globalAlpha = 0.25;
  ctx.strokeStyle = '#16203a';
  ctx.lineWidth = 1;
  const gap = 34;
  for(let x=0;x<W;x+=gap){ ctx.beginPath(); ctx.moveTo(x,0); ctx.lineTo(x,H); ctx.stroke(); }
  for(let y=0;y<H;y+=gap){ ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(W,y); ctx.stroke(); }
  ctx.restore();

  // radial glow behind hub
  const hubPx = toPx(hub.nx, hub.ny);
  const glow = ctx.createRadialGradient(hubPx[0],hubPx[1],0,hubPx[0],hubPx[1],220);
  glow.addColorStop(0, 'rgba(120,140,255,0.22)');
  glow.addColorStop(1, 'rgba(120,140,255,0)');
  ctx.fillStyle = glow;
  ctx.fillRect(0,0,W,H);

  // arcs from hub to destinations
  destinations.forEach((d)=>{
    const p1 = toPx(d.nx, d.ny);
    drawArc(hubPx, p1, 0.35);
  });

