arcParticles.forEach(ap=>{
  ap.t += ap.speed * (1/60);
  if(ap.t > 1) ap.t = 0;
  const p1 = toPx(ap.dest.nx, ap.dest.ny);
  const [x,y] = quadArc(hubPx, p1, ap.t);
  const alpha = Math.sin(ap.t*Math.PI); // fade in/out along path
  ctx.beginPath();
  ctx.arc(x,y,2.4,0,Math.PI*2);
  ctx.fillStyle = `rgba(180,200,255,${0.9*alpha})`;
  ctx.shadowColor = 'rgba(140,170,255,0.9)';
  ctx.shadowBlur = 8;
  ctx.fill();
  ctx.shadowBlur = 0;
});

