// radar sweep — a rotating trailing wedge fanning out from the hub
ctx.save();
ctx.translate(hubPx[0], hubPx[1]);
const sweepR = Math.max(W,H) * 0.55;
const sweepAngle = time * 0.5;
const sweepTrail = 1.1;
const sweepSteps = 20;
for(let s=0;s<sweepSteps;s++){
  const a0 = sweepAngle - sweepTrail*(s/sweepSteps);
  const a1 = sweepAngle - sweepTrail*((s+1)/sweepSteps);
  const a = (1 - s/sweepSteps) * 0.05;
  ctx.beginPath();
  ctx.moveTo(0,0);
  ctx.arc(0,0,sweepR,a1,a0);
  ctx.closePath();
  ctx.fillStyle = `rgba(129,140,255,${a})`;
  ctx.fill();
}
ctx.restore();

