  // ---- Subtle 3D tilt: the map + labels lean toward the cursor for a real depth cue ----
  const wrapEl = document.querySelector('.net-wrap');
  wrapEl.addEventListener('mousemove', (e)=>{
    const r = wrapEl.getBoundingClientRect();
    const nx = ((e.clientX - r.left) / r.width) - 0.5;
    const ny = ((e.clientY - r.top) / r.height) - 0.5;
    wrapEl.style.transform = `rotateY(${nx*7}deg) rotateX(${-ny*7}deg) scale(1.015)`;
  });
  wrapEl.addEventListener('mouseleave', ()=>{
    wrapEl.style.transform = 'rotateY(0deg) rotateX(0deg) scale(1)';
  });
})();

