554	  // Convert normalized polygon points to a dense, textured field of dots via rasterization
555	  function pointInPoly(x,y,poly){
556	    let inside=false;
557	    for(let i=0,j=poly.length-1;i<poly.length;j=i++){
558	      const xi=poly[i][0], yi=poly[i][1], xj=poly[j][0], yj=poly[j][1];
559	      const intersect = ((yi>y)!==(yj>y)) && (x < (xj-xi)*(y-yi)/(yj-yi+0.0000001)+xi);
560	      if(intersect) inside=!inside;
561	    }
562	    return inside;
563	  }
