572	        // skip cells pseudo-randomly for an organic, less grid-locked texture
573	        if(Math.random() < 0.22) continue;
574	        const x = i/cols + (Math.random()-0.5)*jitter;
575	        const y = j/rows + (Math.random()-0.5)*jitter;
576	        for(const poly of landmasses){
577	          if(pointInPoly(x,y,poly)){
578	            const sparkle = Math.random() < 0.06;
