581	              phase: Math.random()*Math.PI*2,
582	              speed: 0.5 + Math.random()*0.9,
583	              r: sparkle ? (1.6 + Math.random()*0.8) : (0.55 + Math.random()*0.75),
584	              base: sparkle ? 0.45 : (0.12 + Math.random()*0.16)
585	            });
586	            break;
587	          }
588	        }
589	      }
590	    }
591	  }
592	  buildDots();
593	
594	  // Hub = Singapore (1.35°N, 103.8°E), projected with the same geo() function as the landmasses
595	  const [hubX, hubY] = geo(103.8, 1.35);
596	  const hub = {nx:hubX, ny:hubY};
597	
598	  // Destination markers at real city coordinates, same projection as the landmasses above
599	  function z(lon,lat){ const [x,y]=geo(lon,lat); return {nx:x, ny:y}; }
600	  const destinations = [
601	    {...z(139.7,35.7),  label:'Japan',     flag:'flag-jp', ms:52, side:'left'},  // Tokyo
602	    {...z(100.5,13.7),  label:'Thailand',  flag:'flag-th', ms:20, side:'top'},   // Bangkok
603	    {...z(105.8,21.0),  label:'Vietnam',   flag:'flag-vn', ms:22, side:'right'}, // Hanoi
604	    {...z(77.2,28.6),   label:'India',     flag:'flag-in', ms:38, side:'left'},  // Delhi
605	    {...z(101.7,3.1),   label:'Malaysia',  flag:'flag-my', ms:18, side:'left'},  // Kuala Lumpur
606	    {...z(106.8,-6.2),  label:'Indonesia', flag:'flag-id', ms:28, side:'bottom'},// Jakarta
607	    {...z(151.2,-33.9), label:'Australia', flag:'flag-au', ms:48, side:'left'},  // Sydney
608	  ];
609	
610	  // Particles traveling along arcs — 2-3 per route, staggered, so each line has a steady flow
611	  const arcParticles = [];
612	  destinations.forEach(d=>{
613	    const count = 2 + (Math.random() < 0.5 ? 1 : 0);
614	    const speed = 0.16 + Math.random()*0.08;
615	    for(let k=0;k<count;k++){
616	      arcParticles.push({ t: k/count, speed, dest: d });
617	    }
618	  });
619	
620	  function toPx(nx, ny){
621	    return [nx*W, ny*H];
622	  }
623	
624	  function quadArc(p0, p1, t){
625	    // control point bows upward/outward for a 3D globe-ish arc
626	    const mx = (p0[0]+p1[0])/2;
627	    const my = (p0[1]+p1[1])/2 - Math.abs(p1[0]-p0[0])*0.28 - 40;
628	    const x = (1-t)*(1-t)*p0[0] + 2*(1-t)*t*mx + t*t*p1[0];
629	    const y = (1-t)*(1-t)*p0[1] + 2*(1-t)*t*my + t*t*p1[1];
630	    return [x,y];
631	  }
632	
633	  function drawArc(p0, p1, alpha){
634	    ctx.beginPath();
635	    const steps = 40;
636	    for(let i=0;i<=steps;i++){
637	      const [x,y] = quadArc(p0,p1,i/steps);
638	      if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
639	    }
640	    const grad = ctx.createLinearGradient(p0[0],p0[1],p1[0],p1[1]);
641	    grad.addColorStop(0, `rgba(167,139,250,${alpha})`);
642	    grad.addColorStop(1, `rgba(59,130,246,${alpha})`);
643	    ctx.strokeStyle = grad;
644	    ctx.lineWidth = 1.4;
645	    ctx.stroke();
646	  }
647	
648	  let t0 = null;
649	  function frame(ts){
650	    if(t0===null) t0 = ts;
651	    const time = (ts - t0)/1000;
652	
653	    ctx.clearRect(0,0,W,H);
654	
655	    // subtle grid background
656	    ctx.save();
657	    ctx.globalAlpha = 0.25;
658	    ctx.strokeStyle = '#16203a';
659	    ctx.lineWidth = 1;
660	    const gap = 34;
661	    for(let x=0;x<W;x+=gap){ ctx.beginPath(); ctx.moveTo(x,0); ctx.lineTo(x,H); ctx.stroke(); }
662	    for(let y=0;y<H;y+=gap){ ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(W,y); ctx.stroke(); }
663	    ctx.restore();
664	
665	    // radial glow behind hub
666	    const hubPx = toPx(hub.nx, hub.ny);
667	    const glow = ctx.createRadialGradient(hubPx[0],hubPx[1],0,hubPx[0],hubPx[1],220);
668	    glow.addColorStop(0, 'rgba(120,140,255,0.22)');
669	    glow.addColorStop(1, 'rgba(120,140,255,0)');
670	    ctx.fillStyle = glow;
671	    ctx.fillRect(0,0,W,H);
672	
673	    // radar sweep — a rotating trailing wedge fanning out from the hub
674	    ctx.save();
675	    ctx.translate(hubPx[0], hubPx[1]);
676	    const sweepR = Math.max(W,H) * 0.55;
677	    const sweepAngle = time * 0.5;
678	    const sweepTrail = 1.1;
679	    const sweepSteps = 20;
680	    for(let s=0;s<sweepSteps;s++){
681	      const a0 = sweepAngle - sweepTrail*(s/sweepSteps);
682	      const a1 = sweepAngle - sweepTrail*((s+1)/sweepSteps);
683	      const a = (1 - s/sweepSteps) * 0.05;
684	      ctx.beginPath();
685	      ctx.moveTo(0,0);
686	      ctx.arc(0,0,sweepR,a1,a0);
687	      ctx.closePath();
688	      ctx.fillStyle = `rgba(129,140,255,${a})`;
689	      ctx.fill();
690	    }
691	    ctx.restore();
692	
693	    // arcs from hub to destinations
694	    destinations.forEach((d)=>{
695	      const p1 = toPx(d.nx, d.ny);
696	      drawArc(hubPx, p1, 0.35);
697	    });
698	
699	    // traveling particles along arcs
700	    arcParticles.forEach(ap=>{
701	      ap.t += ap.speed * (1/60);
702	      if(ap.t > 1) ap.t = 0;
703	      const p1 = toPx(ap.dest.nx, ap.dest.ny);
704	      const [x,y] = quadArc(hubPx, p1, ap.t);
705	      const alpha = Math.sin(ap.t*Math.PI); // fade in/out along path
706	      ctx.beginPath();
707	      ctx.arc(x,y,2.4,0,Math.PI*2);
708	      ctx.fillStyle = `rgba(180,200,255,${0.9*alpha})`;
709	      ctx.shadowColor = 'rgba(140,170,255,0.9)';
710	      ctx.shadowBlur = 8;
711	      ctx.fill();
712	      ctx.shadowBlur = 0;
713	    });
714	
715	    // dotted landmasses, pulsing
716	    dots.forEach(d=>{
717	      const [x,y] = toPx(d.nx, d.ny);
718	      const pulse = 0.5 + 0.5*Math.sin(time*d.speed + d.phase);
719	      const alpha = d.base + pulse*0.3;
720	      ctx.beginPath();
721	      ctx.arc(x,y,d.r,0,Math.PI*2);
722	      ctx.fillStyle = `rgba(110,140,240,${alpha})`;
723	      ctx.fill();
724	    });
725	
726	    // destination pulse markers
727	    destinations.forEach(d=>{
728	      const [x,y] = toPx(d.nx, d.ny);
729	      const pulse = (time*0.6 + d.nx*3) % 1;
730	      // expanding ring
731	      ctx.beginPath();
732	      ctx.arc(x,y, 4 + pulse*14, 0, Math.PI*2);
733	      ctx.strokeStyle = `rgba(140,170,255,${(1-pulse)*0.5})`;
734	      ctx.lineWidth = 1.5;
735	      ctx.stroke();
736	      // core dot
737	      ctx.beginPath();
738	      ctx.arc(x,y,3,0,Math.PI*2);
739	      ctx.fillStyle = 'rgba(200,215,255,0.95)';
740	      ctx.shadowColor = 'rgba(150,180,255,0.9)';
741	      ctx.shadowBlur = 6;
742	      ctx.fill();
743	      ctx.shadowBlur = 0;
744	    });
745	
746	    // hub marker (Singapore) - bright pulsing core with rings
747	    const hubPulse = 0.5 + 0.5*Math.sin(time*2.2);
748	    for(let ring=0; ring<3; ring++){
749	      const rp = ((time*0.5) + ring/3) % 1;
750	      ctx.beginPath();
751	      ctx.arc(hubPx[0], hubPx[1], 6 + rp*46, 0, Math.PI*2);
752	      ctx.strokeStyle = `rgba(160,120,255,${(1-rp)*0.45})`;
753	      ctx.lineWidth = 1.6;
754	      ctx.stroke();
755	    }
756	    ctx.beginPath();
757	    ctx.arc(hubPx[0], hubPx[1], 5 + hubPulse*1.5, 0, Math.PI*2);
758	    const hubGrad = ctx.createRadialGradient(hubPx[0],hubPx[1],0,hubPx[0],hubPx[1],10);
759	    hubGrad.addColorStop(0,'#ffffff');
760	    hubGrad.addColorStop(0.4,'#a78bfa');
761	    hubGrad.addColorStop(1,'rgba(139,92,246,0)');
762	    ctx.fillStyle = hubGrad;
763	    ctx.shadowColor = '#a78bfa';
764	    ctx.shadowBlur = 20;
765	    ctx.fill();
766	    ctx.shadowBlur = 0;
767	
768	    requestAnimationFrame(frame);
769	  }
770	  requestAnimationFrame(frame);
771	
772	  // ---- HTML pill labels (flag + country + latency), positioned from the same nx/ny coords ----
773	  const labelsLayer = document.getElementById('netLabels');
774	  const hubPillEl = document.createElement('div');
775	  hubPillEl.className = 'net-pill hub';
776	  hubPillEl.innerHTML = `<span class="flag flag-sg"></span>Singapore`;
777	  labelsLayer.appendChild(hubPillEl);
778	
779	  const destPillEls = destinations.map(d=>{
780	    const el = document.createElement('div');
781	    el.className = 'net-pill side-' + d.side;
782	    el.innerHTML = `<span class="flag ${d.flag}"></span>${d.label}<span class="ms">${d.ms}ms</span>`;
783	    labelsLayer.appendChild(el);
784	    return el;
785	  });
786	
787	  function layoutLabels(){
788	    hubPillEl.style.left = (hub.nx*100) + '%';
789	    hubPillEl.style.top = (hub.ny*100) + '%';
790	    destinations.forEach((d,i)=>{
791	      const el = destPillEls[i];
792	      el.style.left = (d.nx*100) + '%';
793	      el.style.top = (d.ny*100) + '%';
794	    });
795	  }
796	  layoutLabels();
797	  window.addEventListener('resize', layoutLabels);
798	
799	  window.addEventListener('resize', ()=>{ resize(); });
800	
801	  // ---- Subtle 3D tilt: the map + labels lean toward the cursor for a real depth cue ----
802	  const wrapEl = document.querySelector('.net-wrap');
803	  wrapEl.addEventListener('mousemove', (e)=>{
804	    const r = wrapEl.getBoundingClientRect();
805	    const nx = ((e.clientX - r.left) / r.width) - 0.5;
806	    const ny = ((e.clientY - r.top) / r.height) - 0.5;
807	    wrapEl.style.transform = `rotateY(${nx*7}deg) rotateX(${-ny*7}deg) scale(1.015)`;
808	  });
809	  wrapEl.addEventListener('mouseleave', ()=>{
810	    wrapEl.style.transform = 'rotateY(0deg) rotateX(0deg) scale(1)';
811	  });
812	})();
813	</script>
814	
815	</body>
