.flag-in::after{ content:""; position:absolute; top:47%; left:50%; width:5px; height:5px; border-radius:50%; background:#000088; transform:translate(-50%,-50%); }
.flag-my{ background:repeating-linear-gradient(#cc0001 0 3.5px, #fff 3.5px 7px); position:relative; }
.flag-my::after{ content:""; position:absolute; top:0; left:0; width:55%; height:55%; background:#010066; }
.flag-id{ background:linear-gradient(#cc0001 0 50%, #fff 50% 100%); }
