.flag-au::after{ content:""; position:absolute; top:0; left:0; width:60%; height:60%; background:
    linear-gradient(rgba(255,255,255,0.9) 0 100%) center/2px 100%,
    linear-gradient(rgba(255,255,255,0.9) 0 100%) center/100% 2px;
  background-color:#00247d; background-repeat:no-repeat; }
.flag-sg{ background:linear-gradient(#ed2939 0 50%, #fff 50% 100%); }
.net-pill .ms{
  background:rgba(56,189,248,0.15);
  color:#7dd3fc;
  font-size:11px;
  font-weight:700;
  padding:3px 8px;
  border-radius:12px;
}
.net-pill.hub{ transform:translate(-50%,-50%); }
.net-pill.side-left{  transform:translate(calc(-100% - 12px), -50%); }
