const arcParticles = [];
destinations.forEach(d=>{
  const count = 2 + (Math.random() < 0.5 ? 1 : 0);
  const speed = 0.16 + Math.random()*0.08;
  for(let k=0;k<count;k++){
    arcParticles.push({ t: k/count, speed, dest: d });
  }
});

function toPx(nx, ny){
  return [nx*W, ny*H];
}

function quadArc(p0, p1, t){
  // control point bows upward/outward for a 3D globe-ish arc
  const mx = (p0[0]+p1[0])/2;
  const my = (p0[1]+p1[1])/2 - Math.abs(p1[0]-p0[0])*0.28 - 40;
  const x = (1-t)*(1-t)*p0[0] + 2*(1-t)*t*mx + t*t*p1[0];
  const y = (1-t)*(1-t)*p0[1] + 2*(1-t)*t*my + t*t*p1[1];
  return [x,y];
}

function drawArc(p0, p1, alpha){
  ctx.beginPath();
  const steps = 40;
  for(let i=0;i<=steps;i++){
    const [x,y] = quadArc(p0,p1,i/steps);
    if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
  }
  const grad = ctx.createLinearGradient(p0[0],p0[1],p1[0],p1[1]);
  grad.addColorStop(0, `rgba(167,139,250,${alpha})`);
  grad.addColorStop(1, `rgba(59,130,246,${alpha})`);
  ctx.strokeStyle = grad;
  ctx.lineWidth = 1.4;
  ctx.stroke();
}

let t0 = null;
function frame(ts){
  if(t0===null) t0 = ts;

