input.new_string:
function quadArc(p0, p1, t, curve){
  // control point bows to one side (by `curve`) and always arches slightly
  // "up" out of the straight line, so every route gets its own organic sweep
  // instead of a uniform symmetric bow.
  curve = curve || 0;
  const dx = p1[0]-p0[0], dy = p1[1]-p0[1];
  const dist = Math.hypot(dx,dy) || 1;
  const nx = -dy/dist, ny = dx/dist;
  const mx = (p0[0]+p1[0])/2 + nx*dist*curve*0.32;
  const my = (p0[1]+p1[1])/2 + ny*dist*curve*0.32 - dist*0.14;
  const x = (1-t)*(1-t)*p0[0] + 2*(1-t)*t*mx + t*t*p1[0];
  const y = (1-t)*(1-t)*p0[1] + 2*(1-t)*t*my + t*t*p1[1];
  return [x,y];
}

function drawArc(p0, p1, alpha, curve){
  const steps = 48;
  const pts = [];
  for(let i=0;i<=steps;i++) pts.push(quadArc(p0,p1,i/steps,curve));

  const grad = ctx.createLinearGradient(p0[0],p0[1],p1[0],p1[1]);
  grad.addColorStop(0, `rgba(167,139,250,${alpha})`);
  grad.addColorStop(1, `rgba(59,130,246,${alpha})`);

  // soft outer glow pass
  ctx.beginPath();
  pts.forEach(([x,y],i)=> i===0 ? ctx.moveTo(x,y) : ctx.lineTo(x,y));
  ctx.strokeStyle = grad;
  ctx.lineWidth = 6;
  ctx.globalAlpha = 0.16;
  ctx.shadowColor = 'rgba(120,140,255,0.8)';
  ctx.shadowBlur = 14;
  ctx.stroke();
  ctx.shadowBlur = 0;
  ctx.globalAlpha = 1;

  // bright core line
  ctx.beginPath();
  pts.forEach(([x,y],i)=> i===0 ? ctx.moveTo(x,y) : ctx.lineTo(x,y));
  ctx.strokeStyle = grad;
  ctx.lineWidth = 1.8;
  ctx.stroke();
}

