function frame(ts){
  if(t0===null) t0 = ts;
  const time = (ts - t0)/1000;

  ctx.clearRect(0,0,W,H);

  // subtle grid background
  ctx.save();
  ctx.globalAlpha = 0.25;
  ctx.strokeStyle = '#16203a';
  ctx.lineWidth = 1;
  const gap = 34;
  for(let x=0;x<W;x+=gap){ ctx.beginPath(); ctx.moveTo(x,0); ctx.lineTo(x,H); ctx.stroke(); }
  for(let y=0;y<H;y+=gap){ ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(W,y); ctx.stroke(); }
  ctx.restore();

  // radial glow behind hub
  const hubPx = toPx(hub.nx, hub.ny);
  const glow = ctx.createRadialGradient(hubPx[0],hubPx[1],0,hubPx[0],hubPx[1],220);
  glow.addColorStop(0, 'rgba(120,140,255,0.22)');
  glow.addColorStop(1, 'rgba(120,140,255,0)');
  ctx.fillStyle = glow;
  ctx.fillRect(0,0,W,H);

  // radar sweep — a rotating trailing wedge fanning out from the hub
  ctx.save();
  ctx.translate(hubPx[0], hubPx[1]);
  const sweepR = Math.max(W,H) * 0.55;
  const sweepAngle = time * 0.5;
  const sweepTrail = 1.1;
  const sweepSteps = 20;
  for(let s=0;s<sweepSteps;s++){
    const a0 = sweepAngle - sweepTrail*(s/sweepSteps);
    const a1 = sweepAngle - sweepTrail*((s+1)/sweepSteps);
    const a = (1 - s/sweepSteps) * 0.05;
    ctx.beginPath();
    ctx.moveTo(0,0);
    ctx.arc(0,0,sweepR,a1,a0);
    ctx.closePath();
    ctx.fillStyle = `rgba(129,140,255,${a})`;
    ctx.fill();
  }
  ctx.restore();

  // arcs from hub to destinations
  destinations.forEach((d)=>{
    const p1 = toPx(d.nx, d.ny);
    drawArc(hubPx, p1, 0.35);
  });

  // traveling particles along arcs
  arcParticles.forEach(ap=>{
    ap.t += ap.speed * (1/60);
    if(ap.t > 1) ap.t = 0;
    const p1 = toPx(ap.dest.nx, ap.dest.ny);
    const [x,y] = quadArc(hubPx, p1, ap.t);
    const alpha = Math.sin(ap.t*Math.PI); // fade in/out along path
    ctx.beginPath();
    ctx.arc(x,y,2.4,0,Math.PI*2);
    ctx.fillStyle = `rgba(180,200,255,${0.9*alpha})`;
    ctx.shadowColor = 'rgba(140,170,255,0.9)';
    ctx.shadowBlur = 8;
    ctx.fill();
    ctx.shadowBlur = 0;
  });

  // dotted landmasses, pulsing
  dots.forEach(d=>{
    const [x,y] = toPx(d.nx, d.ny);
    const pulse = 0.5 + 0.5*Math.sin(time*d.speed + d.phase);
    const alpha = d.base + pulse*0.3;
    ctx.beginPath();
    ctx.arc(x,y,d.r,0,Math.PI*2);
    ctx.fillStyle = `rgba(110,140,240,${alpha})`;
    ctx.fill();
  });

  // destination pulse markers
  destinations.forEach(d=>{
    const [x,y] = toPx(d.nx, d.ny);
    const pulse = (time*0.6 + d.nx*3) % 1;
    // expanding ring
    ctx.beginPath();
    ctx.arc(x,y, 4 + pulse*14, 0, Math.PI*2);
    ctx.strokeStyle = `rgba(140,170,255,${(1-pulse)*0.5})`;
    ctx.lineWidth = 1.5;
    ctx.stroke();
    // core dot
    ctx.beginPath();
    ctx.arc(x,y,3,0,Math.PI*2);
    ctx.fillStyle = 'rgba(200,215,255,0.95)';
    ctx.shadowColor = 'rgba(150,180,255,0.9)';
    ctx.shadowBlur = 6;
    ctx.fill();
    ctx.shadowBlur = 0;
  });

  // hub marker (Singapore) - bright pulsing core with rings
  const hubPulse = 0.5 + 0.5*Math.sin(time*2.2);
  for(let ring=0; ring<3; ring++){

