input.new_string:
// perspective floor grid — converges toward a horizon so the map reads as a
// real 3D plane (reinforces the CSS rotateX/Y tilt on mouse-move)
ctx.save();
const vanishX = W*0.52, horizonY = H*0.02;
const vLines = 15, hLines = 11;
ctx.strokeStyle = '#2c3d66';
// verticals: converge toward the vanishing point at the horizon
for(let i=-vLines;i<=vLines;i++){
  const bottomX = vanishX + i * (W*0.09);
  ctx.globalAlpha = Math.max(0, 0.16 - Math.abs(i)*0.007);
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(bottomX, H);
  ctx.lineTo(vanishX, horizonY);
  ctx.stroke();
}
// horizontals: bunch up near the horizon, spread out near the bottom (perspective spacing)
for(let j=1;j<=hLines;j++){
  const d = Math.pow(j/hLines, 1.8); // eased depth 0..1
  const y = horizonY + d*(H-horizonY);
  const halfW = (W*0.62) * d;
  ctx.globalAlpha = 0.05 + 0.13*d;
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(vanishX-halfW, y);
  ctx.lineTo(vanishX+halfW, y);
  ctx.stroke();
}
ctx.restore();

