// hub marker (Singapore) — the brightest point in the whole visualization:
// blue inner glow -> purple outer glow, concentric pulse rings, a slow orbital
// dashed ring, and a bright white-hot core.
const hubPulse = 0.5 + 0.5*Math.sin(time*2.2);

// layered ambient disc right at the hub (blue core fading to purple)
ctx.beginPath();
ctx.arc(hubPx[0], hubPx[1], 34, 0, Math.PI*2);
const discGrad = ctx.createRadialGradient(hubPx[0],hubPx[1],0,hubPx[0],hubPx[1],34);
discGrad.addColorStop(0,'rgba(120,160,255,0.35)');
discGrad.addColorStop(0.55,'rgba(139,92,246,0.20)');
discGrad.addColorStop(1,'rgba(139,92,246,0)');
ctx.fillStyle = discGrad;
ctx.fill();

// slow orbital ring (dashed), constantly rotating — a radar/orbit cue
ctx.save();
ctx.translate(hubPx[0], hubPx[1]);
ctx.rotate(time*0.35);
ctx.beginPath();
ctx.setLineDash([2,7]);
ctx.arc(0,0,26,0,Math.PI*2);
ctx.strokeStyle = 'rgba(150,180,255,0.55)';
ctx.lineWidth = 1.2;
ctx.stroke();
ctx.setLineDash([]);
ctx.restore();

// 3 expanding pulse rings
for(let ring=0; ring<3; ring++){
