// reads as the clear center of the composition. Uses the SAME geo() projection as the
// dotted landmasses above, so the hub and every marker sit exactly on their real
// lon/lat position on the dot map — nothing here is placed by eye.
function z(lon,lat){ const [x,y]=geo(lon,lat); return {nx:x, ny:y}; }
const hub = z(103.8, 1.35); // Singapore

// Destination markers at real city coordinates. `curve` only changes how each arc
// bows on its way there (for an organic, non-symmetrical sweep) — not its endpoint.
const destinations = [
  {...z(139.7,35.7),  label:'Japan',     flag:'flag-jp', ms:52, side:'left',   curve: 1.00}, // Tokyo
  {...z(100.5,13.7),  label:'Thailand',  flag:'flag-th', ms:20, side:'top',    curve:-0.55}, // Bangkok
  {...z(105.8,21.0),  label:'Vietnam',   flag:'flag-vn', ms:22, side:'right',  curve: 0.35}, // Hanoi
  {...z(77.2,28.6),   label:'India',     flag:'flag-in', ms:38, side:'left',   curve:-0.85}, // Delhi
  {...z(101.7,3.1),   label:'Malaysia',  flag:'flag-my', ms:18, side:'left',   curve:-0.20}, // Kuala Lumpur
  {...z(106.8,-6.2),  label:'Indonesia', flag:'flag-id', ms:28, side:'bottom', curve: 0.15}, // Jakarta
  {...z(151.2,-33.9), label:'Australia', flag:'flag-au', ms:48, side:'right',  curve: 0.60}, // Sydney
];

